class Solution:
    def minimizeTheDifference(self, mat: List[List[int]], target: int) -> int:
        sums = {0}
        for row in mat:
            nxt = set()
            for s in sums:
                for v in row:
                    nxt.add(s + v)
            sums = nxt
        return min(abs(s - target) for s in sums)

