class Solution {
public:
    int minimizeTheDifference(vector<vector<int>>& mat, int target) {
        int maxSum = 0;
        for (auto& row : mat)
            maxSum += *max_element(row.begin(), row.end());
        vector<char> dp(maxSum + 1, 0), nxt(maxSum + 1, 0);
        dp[0] = 1;
        for (auto& row : mat) {
            fill(nxt.begin(), nxt.end(), 0);
            for (int s = 0; s <= maxSum; s++) {
                if (!dp[s]) continue;
                for (int v : row) nxt[s + v] = 1;
            }
            swap(dp, nxt);
        }
        for (int d = 0;; d++) {
            if (target - d >= 0 && dp[target - d]) return d;
            if (target + d <= maxSum && dp[target + d]) return d;
        }
    }
};

