class Solution {
    public int minimizeTheDifference(int[][] mat, int target) {
        int maxSum = 0;
        for (int[] row : mat) {
            int mx = 0;
            for (int v : row) mx = Math.max(mx, v);
            maxSum += mx;
        }
        int words = maxSum / 64 + 2;
        long[] dp = new long[words];
        dp[0] = 1L;
        for (int[] row : mat) {
            long[] nxt = new long[words];
            for (int v : row) {
                int ws = v / 64, bs = v % 64;
                for (int w = words - 1; w >= ws; w--) {
                    long chunk = dp[w - ws] << bs;
                    if (bs > 0 && w - ws - 1 >= 0)
                        chunk |= dp[w - ws - 1] >>> (64 - bs);
                    nxt[w] |= chunk;
                }
            }
            dp = nxt;
        }
        for (int d = 0;; d++) {
            if (target - d >= 0 && get(dp, target - d)) return d;
            if (target + d <= maxSum && get(dp, target + d)) return d;
        }
    }

    private boolean get(long[] dp, int pos) {
        return ((dp[pos / 64] >>> (pos % 64)) & 1) == 1;
    }
}

